    sums = Counter(r + c for r, c, v in marks)
    diffs = Counter(c - r for r, c, v in marks)
    use_sum = max(sums.values(), default=0) > max(diffs.values(), default=0)
    key = (lambda r, c: r + c) if use_sum else (lambda r, c: c - r)
    period = None
